            margin-bottom: 15px;
            padding-bottom: 10px;
            border-bottom: 1px solid rgba(255, 255, 255, 0.1);
        }

        .tab-button {
            cursor: pointer;
            transition: transform 0.2s ease-in-out, box-shadow 0.3s ease;
            border-radius: 50%;
            border: 3px solid transparent;
            padding: 2px;
        }

        .tab-button:hover {
            transform: scale(1.1);
        }

        .tab-button.active {
            border-color: var(--accent-color);
            animation: pulse 2s infinite;
        }

        .tab-button img, .tab-button .emoji-button {
            width: 50px;
            height: 50px;
            border-radius: 50%;
            object-fit: cover;
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 30px;
            background-color: rgba(255, 255, 255, 0.1);
        }

        .tab-pane {
            display: none;
            animation: fadeIn 0.5s ease-out forwards;
        }

        .tab-pane.active {
            display: block;
        }

        .tab-pane h3 {
            text-align: center;
            color: var(--accent-color);
            margin-top: 0;
            margin-bottom: 15px;
            font-weight: 600;
        }

        .tab-pane .emoji {
            margin-right: 8px;
        }

