            margin-bottom: 10px;
            display: flex;
            justify-content: space-between;
            align-items: center;
            font-size: 1rem;
        }

        .property-name {
            color: var(--secondary-color);
        }

        .property-value {
            color: var(--primary-color);
            font-weight: 500;
        }

    </style>
</head>
<body>

<div class="status-bar">
    <div class="tabs">
        <div class="tab-button active" onclick="showTab('world', this)">
            <span class="emoji-button">🌍</span>
        </div>
        <div class="tab-button" onclick="showTab('mio', this)">
            <img src="https://files.catbox.moe/rr38k7.png" alt="Mio">
        </div>
        <div class="tab-button" onclick="showTab('yui', this)">
            <img src="https://files.catbox.moe/mx52yc.png" alt="Yui">
        </div>
    </div>

    <div class="tab-content">
        <div id="world" class="tab-pane active">
            <h3><span class="emoji">🌐</span> 世界狀態</h3>
            <div class="property">
                <span class="property-name">📅 日期</span>
                <span id="world-date" class="property-value">--</span>
            </div>
            <div class="property">
                <span class="property-name">⏰ 時間</span>
                <span id="world-time" class="property-value">--</span>
            </div>
        </div>

        <div id="mio" class="tab-pane">
            <h3><span class="emoji">🐍</span> 澪的狀態</h3>
            <div class="property">
                <span class="property-name">📍 地點</span>
                <span id="mio-location" class="property-value">--</span>
            </div>
            <div class="property">
                <span class="property-name">🌡️ 體溫</span>
                <span id="mio-temp" class="property-value">--°C</span>
            </div>
        </div>

        <div id="yui" class="tab-pane">
            <h3><span class="emoji">🦎</span> 結的狀態</h3>
            <div class="property">
                <span class="property-name">📍 地點</span>
                <span id="yui-location" class="property-value">--</span>
            </div>
            <div class="property">
                <span class="property-name">🌡️ 體溫</span>
                <span id="yui-temp" class="property-value">--°C</span>
            </div>
        </div>
    </div>
</div>

<script>
    function showTab(tabId, element) {
        const panes = document.querySelectorAll('.tab-pane');
        panes.forEach(pane => pane.classList.remove('active'));

        const buttons = document.querySelectorAll('.tab-button');
        buttons.forEach(button => button.classList.remove('active'));

        document.getElementById(tabId).classList.add('active');
        element.classList.add('active');
    }

    function SafeGetValue(obj, path, defaultValue = "--") {
        let keys = Array.isArray(path) ? path : path.split('.');
        let current = obj;
        for (let i = 0; i < keys.length; i++) {
            if (current === undefined || current === null || typeof current !== 'object' || !current.hasOwnProperty(keys[i])) {
                return defaultValue;
            }
            current = current[keys[i]];
        }
        return (current === undefined || current === null) ? defaultValue : String(current);
    }

    async function initDisplay() {
        try {
            const messages = await getChatMessages(getCurrentMessageId());
            if (!messages || messages.length === 0 || !messages[0].data) {
                console.error("无法加载状态数据 (messages empty)");
                return;
            }
            const gameData = messages[0].data;
            const characterData = gameData.stat_data;
            if (!characterData) {
                console.error("无法加载状态数据 (characterData missing)");
                return;
            }

            // Update World Tab
            const year = SafeGetValue(characterData, '世界.年分');
            const month = SafeGetValue(characterData, '世界.月份');
            const day = SafeGetValue(characterData, '世界.日期');
            const weekday = SafeGetValue(characterData, '世界.星期');
            document.getElementById('world-date').innerText = `${year}年${month}月${day}日 (星期${weekday})`;
            document.getElementById('world-time').innerText = SafeGetValue(characterData, '世界.時間');

            // Update Mio Tab
            document.getElementById('mio-location').innerText = SafeGetValue(characterData, '澪.地點');
            document.getElementById('mio-temp').innerText = `${SafeGetValue(characterData, '澪.體溫')}°C`;

            // Update Yui Tab
            document.getElementById('yui-location').innerText = SafeGetValue(characterData, '結.地點');
            document.getElementById('yui-temp').innerText = `${SafeGetValue(characterData, '結.體溫')}°C`;

        } catch (error) {
            console.error("状态栏加载出错:", error);
        }
    }

    document.addEventListener('DOMContentLoaded', () => {
        // Initial load
        initDisplay();

        // Set the first tab as active on load
        showTab('world', document.querySelector('.tab-button'));
    });
</script>
</body>
</html>
